export const getHead = (repo, branch, token) =>
  conditional(`/repos/${repo}/commits/${encodeURIComponent(branch)}`, token, {
    transform: (c) => ({ sha: c.sha, committedAt: c.commit?.committer?.date ?? c.commit?.author?.date ?? null }),
  });

