// Drives the real dashboard page in Chromium against a stubbed api.github.com, and
// reports the ORDER the sweep asked for things in. Parameterised: --url, --members,
// --shot.
import { chromium } from 'playwright';

const arg = (n, d) => { const i = process.argv.indexOf(`--${n}`); return i === -1 ? d : process.argv[i + 1]; };
const URL_ = arg('url', 'http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8099/packs/claudinite-dashboard/');
const N = Number(arg('members', 6));
const SHOT = arg('shot', '/tmp/fleet.png');

const browser = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium' });
const page = await browser.newPage({ viewport: { width: 1280, height: 1400 } });

await page.addInitScript(({ n }) => {
  window.__calls = [];
  const repos = Array.from({ length: n }, (_, i) => `acme/r${i + 1}`);
  const json = (body, status = 200) => new Response(JSON.stringify(body), {
    status, headers: { 'content-type': 'application/json', etag: 'W/"x"', 'x-ratelimit-remaining': '4900', 'x-ratelimit-limit': '5000' },
  });
  const text = (body) => new Response(body, { status: 200, headers: { etag: 'W/"x"', 'x-ratelimit-remaining': '4900', 'x-ratelimit-limit': '5000' } });
  const real = window.fetch.bind(window);
  window.fetch = async (input, init) => {
    const url = typeof input === 'string' ? input : input.url;
    if (!url.includes('api.github.com')) return real(input, init);
    const path = url.replace('https://api.github.com', '');
    window.__calls.push(path);
    // A little latency, so a depth-first sweep would visibly interleave.
    await new Promise((r) => setTimeout(r, 5));
    const repo = (path.match(/^\/repos\/([^/]+\/[^/]+)/) ?? [])[1];
    if (path === '/rate_limit') return json({ resources: { core: { remaining: 4900, limit: 5000, reset: Math.floor(Date.now() / 1000) + 3600 } } });
    if (/\/contents\/.claudinite-settings.json/.test(path)) {
      return text(JSON.stringify({
        packs: ['basics', 'claudinite-dashboard'],
        claudinite: { engineVersion: '60824.1', packVersions: { basics: '60824.1' } },
      }));
    }
    if (/\/contents\//.test(path)) return json({ message: 'Not Found' }, 404);
    if (/\/commits\//.test(path)) return json({ sha: `sha${repo}`, commit: { committer: { date: new Date(Date.now() - 36e5).toISOString() } } });
    if (/\/issues\?/.test(path)) return json([]);
    if (/\/actions\/runs/.test(path)) return json({ workflow_runs: [] });
    if (/\/git\/trees\//.test(path)) return json({ tree: [{ path: '.claudinite/shared/packs/basics/tasks/baselining/task.mjs' }], truncated: false });
    if (/\/stats\/commit_activity/.test(path)) return json([]);
    if (/\/releases\/latest/.test(path)) return json({ message: 'Not Found' }, 404);
    if (repos.includes(repo)) return json({ default_branch: 'main', private: false, full_name: repo, stargazers_count: 3, archived: false });
    return json({ message: 'Not Found' }, 404);
  };
}, { n: N });

page.on('pageerror', (e) => console.log('PAGE ERROR:', e.message));
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE ERROR:', m.text()); });

await page.goto(URL_, { waitUntil: 'networkidle' });
await page.waitForFunction(() => document.getElementById('fleet-progress')?.textContent?.includes('repos read')
  && !document.getElementById('fleet-progress').textContent.includes('…'), null, { timeout: 30000 });

const calls = await page.evaluate(() => window.__calls);
const kind = (p) => (/\/contents\//.test(p) ? 'settings'
  : /\/commits\//.test(p) ? 'head'
    : /\/issues\?/.test(p) ? 'issues'
      : /\/actions\/runs/.test(p) ? 'runs'
        : /\/git\/trees\//.test(p) ? 'tree'
          : /\/stats\/commit_activity/.test(p) ? 'commits'
            : /^\/repos\/[^/]+\/[^/]+$/.test(p) ? 'repo' : 'other');

console.log('\ncall order:');
console.log(calls.map(kind).join(' '));
const first = (k) => calls.findIndex((c) => kind(c) === k);
const last = (k) => calls.map(kind).lastIndexOf(k);
for (const [a, b] of [['head', 'issues'], ['issues', 'tree'], ['tree', 'commits']]) {
  const ok = last(a) === -1 || first(b) === -1 || last(a) < first(b);
  console.log(`${ok ? 'OK  ' : 'FAIL'} every ${a} read before the first ${b} read (last ${a} @${last(a)}, first ${b} @${first(b)})`);
}
console.log('\nprogress line:', await page.textContent('#fleet-progress'));
console.log('footnote:', await page.textContent('#footnote'));
console.log('rows:', await page.locator('#fleet tbody.m').count());

await page.screenshot({ path: SHOT, fullPage: false });
await browser.close();

